def eprint(s=""):
    print(s, file=sys.stderr)


def natural_chunks(s):
    parts = []
    for part in re.findall(r'\d+|\D+', s):
        if part.isdigit():
            # Numeric value first, original digits as a tie breaker (so 01 sorts before 1).
            parts.append((1, int(part), part))
        else:
            parts.append((0, part))
    return parts


def natural_cmp(a, b):
    ka = natural_chunks(a)
    kb = natural_chunks(b)
    n = min(len(ka), len(kb))
    for i in range(n):
        x, y = ka[i], kb[i]
        if x[0] != y[0]:
            # Keep strings before numbers, matching ordinary natural-sort behavior.
            return -1 if x[0] < y[0] else 1
        if x[0] == 0:
            if x[1] != y[1]:
                return -1 if x[1] < y[1] else 1
        else:
            if x[1] != y[1]:
                return -1 if x[1] < y[1] else 1
            if x[2] != y[2]:
                return -1 if x[2] < y[2] else 1
    if len(ka) != len(kb):
        return -1 if len(ka) < len(kb) else 1
    return 0


def natural_key(s):
    return cmp_to_key(natural_cmp)(s)


def sort_strings(seq, reverse=False):
    return sorted(seq, key=cmp_to_key(natural_cmp), reverse=reverse)


def split_ext(rel):
    d, base = os.path.split(rel)
    stem, ext = os.path.splitext(base)
    return d, stem, ext


def append_ext(out, ext):
    if not ext:
        return out
    return out + ext


def prefix_basename(path, prefix="_"):
    d, b = os.path.split(path)
    nb = prefix + b
    return os.path.join(d, nb) if d else nb


class FormatError(Exception):
    pass


def format_value(val, pad):
    if pad is None:
        return val
    if re.fullmatch(r'\d+', val or ""):
        return val.zfill(pad)
    return val


def eval_format(fmt, values):
    """values accepts int keys and string keys. Missing keys produce ''."""
    res = []
    i = 0
    auto = 1
    while i < len(fmt):
        c = fmt[i]
        if c == '\\' and i + 1 < len(fmt) and fmt[i+1] in '{}':
            res.append(fmt[i+1])
            i += 2
            continue
        if c == '}':
            raise FormatError("an unopened placeholder could not be closed by '}'")
        if c == '{':
            j = fmt.find('}', i+1)
            if j < 0:
                raise FormatError("all opened placeholders must be closed by '}'")
            content = fmt[i+1:j]
            if ':' in content:
                group_s, pad_s = content.split(':', 1)
                if pad_s == "" or not pad_s.isdigit():
                    raise FormatError(f"unable to parse padding of '{pad_s}'")
                pad = int(pad_s)
            else:
                group_s, pad = content, None
            if group_s == "":
                key = auto
                auto += 1
            else:
                if group_s.isdigit():
                    key = int(group_s)
                else:
                    key = group_s
            val = values.get(key, "")
            if val is None:
                val = ""
            res.append(format_value(str(val), pad))
            i = j + 1
            continue
        res.append(c)
        i += 1
    return ''.join(res)


def print_table(rows):
    if not rows:
        return
    w1 = max(len("Input"), *(len(r[0]) for r in rows))
    w2 = max(len("Output"), *(len(r[1]) for r in rows))
    border = "+" + "-"*(w1+2) + "+" + "-"*(w2+2) + "+"
    print(border)
    print(f"| {'Input'.ljust(w1)} | {'Output'.ljust(w2)} |")
    print(border)
    for inp, out in rows:
        print(f"| {inp.ljust(w1)} | {out.ljust(w2)} |")
    print(border)


def list_immediate(base):
    try:
        names = os.listdir(base)
    except OSError as e:
        raise
    return sort_strings(names)


def list_depth(base, exact_depth=None, max_depth=None):
    out = []
    def rec(rel_prefix, depth):
        full = os.path.join(base, rel_prefix) if rel_prefix else base
        try:
            names = sort_strings(os.listdir(full))
        except OSError:
            return
        for name in names:
            rel = os.path.join(rel_prefix, name) if rel_prefix else name
            rel = rel.replace(os.sep, '/')
            d = depth + 1
            full2 = os.path.join(base, rel)
            include = False
            if exact_depth is not None:
                include = (d == exact_depth)
            elif max_depth is not None:
                include = (d <= max_depth)
            if include:
                out.append(rel)
            if os.path.isdir(full2):
                if exact_depth is not None:
                    if d < exact_depth:
                        rec(rel, d)
                elif max_depth is not None:
                    if d < max_depth:
                        rec(rel, d)
    rec('', 0)
    return out


def rows_sort(base, order, fmt, preserve_ext):
    names = list_immediate(base)
    names = sort_strings(names, reverse=(order == 'desc'))
    pairs = []
    for idx, rel in enumerate(names, 1):
        vals = {0: rel, 1: str(idx)}
        out = eval_format(fmt, vals)
        if preserve_ext:
            _, _, ext = split_ext(rel)
            out = append_ext(out, ext)
        pairs.append((rel, out.replace(os.sep, '/')))
    return pairs


def python_regex_error(pattern, exc):
    msg = str(exc)
    if 'unterminated character set' in msg:
        msg2 = 'unclosed character class'
    elif 'nothing to repeat' in msg:
        msg2 = 'repetition operator missing expression'
    else:
        # Trim Python's position suffix when possible for a Rust-like message.
        msg2 = re.sub(r' at position \d+', '', msg)
    eprint("error: regex parse error:")
    eprint(f"    {pattern}")
    eprint("    ^")
    eprint(f"error: {msg2}")


def rows_regex(base, pattern, fmt, preserve_ext, depth, max_depth):
    try:
        rx = re.compile(pattern)
    except re.error as exc:
        python_regex_error(pattern, exc)
        sys.exit(1)
    if max_depth is not None:
        entries = list_depth(base, max_depth=max_depth)
    else:
        if depth is None:
            depth = pattern.count('/') + 1
        entries = list_depth(base, exact_depth=depth)
    pairs = []
    for rel in entries:
        rel_slash = rel.replace(os.sep, '/')
        m = rx.search(rel_slash)
        if not m:
            continue
        vals = {0: m.group(0)}
        for i in range(1, len(m.groups()) + 1):
            vals[i] = m.group(i) or ""
        vals.update({k: (v or "") for k, v in m.groupdict().items()})
        out = eval_format(fmt, vals)
        if preserve_ext:
            _, _, ext = split_ext(rel_slash)
            out = append_ext(out, ext)
        pairs.append((rel_slash, out.replace(os.sep, '/')))
    return pairs


def rows_map(map_path):
    try:
        with open(map_path, 'r', encoding='utf-8') as f:
            data = json.load(f)
    except OSError as e:
        eprint(f"error: {e.strerror} (os error {e.errno})")
        sys.exit(1)
    except Exception as e:
        eprint(f"error: {e}")
        sys.exit(1)
    if not isinstance(data, dict):
        eprint("error: invalid map file")
        sys.exit(1)
    return [(str(k), str(v)) for k, v in data.items()]


def resolve_conflicts(base, pairs, overwrite):
    # Later duplicate raw outputs win when overwriting.
    if overwrite:
        d = {}
        order = []
        for inp, out in pairs:
            if out in d:
                # keep insertion place roughly with latest value; displayed sorting is by output anyway
                d[out] = inp
            else:
                d[out] = inp
                order.append(out)
        return [(d[o], o) for o in order if o in d]

    inputs = set(inp for inp, _ in pairs)
    used = set()
    resolved = []
    for inp, raw in pairs:
        out = raw
        raw_full = os.path.join(base, *raw.split('/'))
        raw_exists = os.path.exists(raw_full)
        if raw in used or (raw_exists and raw != inp):
            out = prefix_basename(out)
            while True:
                full = os.path.join(base, *out.split('/'))
                if out not in used and (not os.path.exists(full) or out in inputs):
                    break
                out = prefix_basename(out)
        while out in used:
            out = prefix_basename(out)
        used.add(out)
        resolved.append((inp, out))
    return resolved


def sort_rows_for_display(rows):
    return sorted(rows, key=cmp_to_key(lambda a, b: natural_cmp(a[1], b[1]) or natural_cmp(a[0], b[0])))


def rename_rows(base, rows, mkdirs, overwrite):
    display_rows = sort_rows_for_display(rows)
    exec_rows = display_rows if overwrite else list(reversed(display_rows))
    for inp, out in exec_rows:
        src = os.path.join(base, *inp.split('/'))
        dst = os.path.join(base, *out.split('/'))
        if mkdirs:
            parent = os.path.dirname(dst)
            if parent:
                os.makedirs(parent, exist_ok=True)
        try:
            if overwrite:
                os.replace(src, dst)
            else:
                os.rename(src, dst)
        except OSError as e:
            msg = e.strerror or "error"
            eprint(f"[error] unable to rename '{inp}': {msg} (os error {e.errno})")
            sys.exit(1)
    return display_rows


def write_generate(path, rows):
    data = {out: inp for inp, out in rows}
    try:
        parent = os.path.dirname(path)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(path, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2)
    except OSError as e:
        eprint(f"error: {e.strerror} (os error {e.errno})")
        sys.exit(1)


def invalid_output_format(exc):
    eprint(f"error: [output-format] {exc}")
    sys.exit(1)


def parse_int_value(s):
    try:
        return int(s)
    except Exception:
        eprint(f"error: invalid digit found in string")
        sys.exit(1)


def parse_args(argv):
    opts = {
        'dir': '.', 'depth': None, 'no_ext': False, 'generate': None, 'mkdir': False,
        'map': None, 'max_depth': None, 'quiet': False, 'regex': None, 'sort': None,
        'test': False, 'overwrite': False, 'pos': []
    }
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == '--':
            opts['pos'].extend(argv[i+1:]); break
        if a in ('--help',):
            print_long_help(); sys.exit(0)
        if a == '-h':
            print_short_help(); sys.exit(0)
        if a in ('--version', '-V'):
            print(VERSION); sys.exit(0)
        if a in ('-d', '--dir'):
            i += 1
            if i >= len(argv):
                eprint("error: a value is required for '--dir <PATH>'") ; sys.exit(2)
            opts['dir'] = argv[i]
        elif a == '--depth':
            i += 1
            if i >= len(argv): eprint("error: a value is required for '--depth <DEPTH>'"); sys.exit(2)
            opts['depth'] = parse_int_value(argv[i])
        elif a in ('-E', '--no-extension'):
            opts['no_ext'] = True
        elif a in ('-g', '--generate'):
            i += 1
            if i >= len(argv): eprint("error: a value is required for '--generate <PATH>'"); sys.exit(2)
            opts['generate'] = argv[i]
        elif a in ('-k', '--mkdir'):
            opts['mkdir'] = True
        elif a in ('-m', '--map', '--from-file'):
            i += 1
            if i >= len(argv): eprint("error: a value is required for '--map <PATH>'"); sys.exit(2)
            opts['map'] = argv[i]
        elif a == '--max-depth':
            i += 1
            if i >= len(argv): eprint("error: a value is required for '--max-depth <DEPTH>'"); sys.exit(2)
            opts['max_depth'] = parse_int_value(argv[i])
        elif a in ('-q', '--quiet'):
            opts['quiet'] = True
        elif a in ('-r', '--regex'):
            i += 1
            if i >= len(argv): eprint("error: a value is required for '--regex <PATTERN>'"); sys.exit(2)
            opts['regex'] = argv[i]
        elif a in ('-s', '--sort'):
            i += 1
            if i >= len(argv): eprint("error: a value is required for '--sort <ORDER>'"); sys.exit(2)
            if argv[i] not in ('asc', 'desc'):
                eprint(f"error: invalid value '{argv[i]}' for '--sort <ORDER>'")
                eprint("  [possible values: asc, desc]\n")
                eprint("For more information, try '--help'.")
                sys.exit(2)
            opts['sort'] = argv[i]
        elif a in ('-t', '--test', '--dry-run'):
            opts['test'] = True
        elif a in ('-w', '--overwrite'):
            opts['overwrite'] = True
        elif a.startswith('-'):
            eprint(f"error: unexpected argument '{a}' found\n")
            eprint(f"  tip: to pass '{a}' as a value, use '-- {a}'\n")
            eprint(f"Usage: {prog_name()} [OPTIONS] [[SOURCE] OUTPUT]...\n")
            eprint("For more information, try '--help'.")
            sys.exit(2)
        else:
            opts['pos'].append(a)
        i += 1
    return opts


def main():
    opts = parse_args(sys.argv[1:])
    base = opts['dir']

    # Validate directory when a mode actually needs it. Match the concise OS error style.
    if not os.path.isdir(base):
        eprint("error: No such file or directory (os error 2)")
        sys.exit(1)

    pos = opts['pos']
    mode_flags = sum(1 for x in (opts['map'], opts['regex'], opts['sort']) if x is not None)
    if opts['map'] is not None:
        mode = 'map'
        fmt = None
    elif opts['sort'] is not None:
        mode = 'sort'
        if len(pos) == 0:
            eprint("error: [output-format] output formatter must be set")
            sys.exit(1)
        if len(pos) > 1:
            eprint("error: optional SOURCE must be used without setting regex, map or sort flags")
            sys.exit(1)
        fmt = pos[-1]
    elif opts['regex'] is not None:
        mode = 'regex'
        if len(pos) == 0:
            eprint("error: the following required arguments were not provided:")
            eprint("  <[SOURCE] OUTPUT>...\n")
            eprint(f"Usage: {prog_name()} --regex <PATTERN> <[SOURCE] OUTPUT>...\n")
            eprint("For more information, try '--help'.")
            sys.exit(2)
        if len(pos) > 1:
            eprint("error: optional SOURCE must be used without setting regex, map or sort flags")
            sys.exit(1)
        fmt = pos[-1]
    else:
        if len(pos) < 2:
            eprint("error: one of 'regex', 'sort', 'map' or 'SOURCE' options must be set.")
            eprint(f"usage: run '{sys.argv[0]} --help' for more information.")
            sys.exit(1)
        mode = 'regex'
        opts['regex'] = pos[-2]
        fmt = pos[-1]

    try:
        if mode == 'map':
            pairs = rows_map(opts['map'])
        elif mode == 'sort':
            pairs = rows_sort(base, opts['sort'], fmt, not opts['no_ext'])
        else:
            pairs = rows_regex(base, opts['regex'], fmt, not opts['no_ext'], opts['depth'], opts['max_depth'])
    except FormatError as e:
        invalid_output_format(e)
    except OSError as e:
        eprint(f"error: {e.strerror} (os error {e.errno})")
        sys.exit(1)

    try:
        pairs = resolve_conflicts(base, pairs, opts['overwrite'])
    except Exception as e:
        eprint(f"error: {e}")
        sys.exit(1)
    rows_display = sort_rows_for_display(pairs)

    if not opts['test']:
        rows_display = rename_rows(base, pairs, opts['mkdir'], opts['overwrite'])

    if opts['generate'] is not None:
        write_generate(opts['generate'], rows_display)

    if not opts['quiet']:
        print_table(rows_display)

if __name__ == '__main__':
    main()
